// Opt-in same-kernel native runner for an explicitly precompiled *fixed* circuit.
// The numerical recurrence, sparse Pauli hash maps, fixed-channel stages and
// observable accumulation order come from native_pauli.cpp unchanged.
// A newly changed topology/noise/observable needs a NEW plan generated by the
// full Python compiler. No security or production acceptance is implied.
#include <algorithm>
#include <array>
#include <cerrno>
#include <cstdlib>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <thread>
#include <utility>
#include <vector>
#include <zlib.h>

struct CStage {
 int32_t q0,q1,arity,param;
 double ptm[256];
 double dptm[256];
};
struct CTerm {uint64_t x[4],z[4];double coef;};
struct CStats {uint64_t peak_terms,final_terms;};
extern "C" int run_pauli_indexed(int,int,int,const CStage*,int,const int32_t*,
                                      int,const CTerm*,int,uint64_t,double*,CStats*);

static constexpr uint32_t MAX_STAGES=10000,MAX_OBS=500,MAX_TERMS=15000;
static constexpr int MAX_VECTORS=32;
static_assert(sizeof(CStage)==4112,"unexpected native stage ABI");
static_assert(sizeof(CTerm)==72,"unexpected native term ABI");
using Clock=std::chrono::steady_clock;
inline double elapsed_ms(Clock::time_point start){return std::chrono::duration<double,std::milli>(Clock::now()-start).count();}

struct Cone {
 std::vector<int32_t> indices;
 std::vector<CTerm> terms;
 uint32_t wire_count=0;
};
struct Plan {
 int nqubits=0,nparams=0,max_terms=0;
 std::vector<CStage> stages;
 std::vector<double> bases;
 std::vector<Cone> cones;
 double load_ms=0;
};

uint32_t read_u32(const std::vector<unsigned char>& b,size_t& i){
 if(i+4>b.size())throw std::runtime_error("truncated plan integer");
 uint32_t v=0;for(int j=0;j<4;j++)v|=static_cast<uint32_t>(b[i+j])<<(8*j);i+=4;return v;
}

Plan load_plan(const std::string& path){
 auto start=Clock::now();
 std::ifstream f(path,std::ios::binary|std::ios::ate);
 if(!f)throw std::runtime_error("compiled plan file not accessible");
 auto n=f.tellg();if(n<40||n>80*1024*1024)throw std::runtime_error("invalid compiled plan size");
 std::vector<unsigned char> b(static_cast<size_t>(n));
 f.seekg(0);if(!f.read(reinterpret_cast<char*>(b.data()),n))throw std::runtime_error("failed reading plan");
 if(std::memcmp(b.data(),"VCPLN001",8)!=0)throw std::runtime_error("invalid plan signature");
 size_t i=8;
 uint32_t version=read_u32(b,i),nq=read_u32(b,i),np=read_u32(b,i),ns=read_u32(b,i),no=read_u32(b,i);
 uint32_t maxterms=read_u32(b,i),stage_size=read_u32(b,i),crc=read_u32(b,i);
 if(version!=1||nq!=127||(np!=2 && np!=4)||ns>MAX_STAGES||ns<1||no!=127||
    maxterms<128||maxterms>MAX_TERMS||stage_size!=sizeof(CStage))throw std::runtime_error("plan contract mismatch");
 auto actual=crc32(0L,Z_NULL,0);
 actual=crc32(actual,reinterpret_cast<const Bytef*>(b.data()+i),static_cast<uInt>(b.size()-i));
 if(actual!=crc)throw std::runtime_error("plan CRC corruption");
 Plan plan;plan.nqubits=nq;plan.nparams=np;plan.max_terms=maxterms;
 auto ensure=[&](size_t amount){if(amount>b.size()-i)throw std::runtime_error("truncated plan data");};
 ensure(static_cast<size_t>(ns)*sizeof(CStage));plan.stages.resize(ns);
 std::memcpy(plan.stages.data(),b.data()+i,static_cast<size_t>(ns)*sizeof(CStage));i+=static_cast<size_t>(ns)*sizeof(CStage);
 ensure(static_cast<size_t>(ns)*sizeof(double));plan.bases.resize(ns);
 std::memcpy(plan.bases.data(),b.data()+i,static_cast<size_t>(ns)*sizeof(double));i+=static_cast<size_t>(ns)*sizeof(double);
 for(uint32_t k=0;k<ns;k++){
    CStage const& st=plan.stages[k];
    if(st.arity<1||st.arity>2||st.q0<0||st.q0>=static_cast<int>(nq)||st.param<-1||st.param>=static_cast<int>(np)||
        (st.arity==2&&(st.q1<0||st.q1>=static_cast<int>(nq)||st.q1==st.q0)))throw std::runtime_error("invalid stage");
    if(st.param>=0){if(st.arity!=1||!std::isfinite(plan.bases[k]))throw std::runtime_error("only parametric single-wire RZ plans supported");}
 }
 plan.cones.reserve(no);
 for(uint32_t q=0;q<no;q++){
    uint32_t nc=read_u32(b,i),nt=read_u32(b,i),nw=read_u32(b,i);
    if(nc>ns||nt>MAX_TERMS||nw>nq)throw std::runtime_error("invalid cone bounds");
    Cone c;c.wire_count=nw;c.indices.resize(nc);c.terms.resize(nt);
    ensure(static_cast<size_t>(nc)*sizeof(int32_t));std::memcpy(c.indices.data(),b.data()+i,static_cast<size_t>(nc)*sizeof(int32_t));i+=static_cast<size_t>(nc)*sizeof(int32_t);
    ensure(static_cast<size_t>(nt)*sizeof(CTerm));std::memcpy(c.terms.data(),b.data()+i,static_cast<size_t>(nt)*sizeof(CTerm));i+=static_cast<size_t>(nt)*sizeof(CTerm);
    for(auto j:c.indices)if(j<0||j>=static_cast<int>(ns))throw std::runtime_error("invalid cone stage reference");
    plan.cones.push_back(std::move(c));
 }
 if(i!=b.size())throw std::runtime_error("trailing plan data");
 plan.load_ms=elapsed_ms(start);return plan;
}

// Conjugation of Pauli observables by RZ: basis [I,X,Z,Y].
// The same transfer matrix and mathematical derivative as the NumPy path,
// calculated directly from sin/cos instead of 2x2 complex matrix products.
// The last few ulps can differ; correctness is tolerance-gated in tests.
void bind(Plan& p,const std::vector<double>& theta){
 for(size_t i=0;i<p.stages.size();i++){
    auto& s=p.stages[i];if(s.param<0)continue;
    double a=p.bases[i]+theta[s.param],c=std::cos(a),v=std::sin(a);
    std::fill_n(s.ptm,16,0.);std::fill_n(s.dptm,16,0.);
    s.ptm[0]=1.;s.ptm[5]=c;s.ptm[7]=-v;s.ptm[10]=1.;s.ptm[13]=v;s.ptm[15]=c;
    s.dptm[5]=-v;s.dptm[7]=-c;s.dptm[13]=c;s.dptm[15]=-v;
 }
}

std::vector<double> evaluate(Plan& p,int threads){
 auto n=p.cones.size();
 std::vector<std::array<double,17>> out(n);
 std::vector<int> statuses(n,0);
 std::atomic<size_t> cursor{0};
 auto thread_func=[&](){
    while(true){size_t i=cursor.fetch_add(1,std::memory_order_relaxed);if(i>=n)break;
      CStats stats{};auto& c=p.cones[i];
      statuses[i]=run_pauli_indexed(p.nqubits,p.nparams,static_cast<int>(c.indices.size()),p.stages.data(),
             static_cast<int>(p.stages.size()),c.indices.data(),static_cast<int>(c.terms.size()),
             c.terms.data(),0,p.max_terms,out[i].data(),&stats);
    }
 };
 std::vector<std::thread> work;
 for(int i=1;i<threads;i++)work.emplace_back(thread_func);
 thread_func();for(auto& t:work)t.join();
 for(int i:statuses)if(i==-1)throw std::runtime_error("exact Pauli term cap exceeded");
 else if(i)throw std::runtime_error("native numerical kernel error "+std::to_string(i));
 std::vector<double> sum(p.nparams+1,0.);
 // Accumulate the exact same nobs order as IndexedBatchPrepared Python.
 for(auto const& x:out)for(int k=0;k<=p.nparams;k++)sum[k]+=x[k];
 return sum;
}

struct JsonParser {
 std::string s;size_t i=0;
 explicit JsonParser(std::string text):s(std::move(text)){}
 void ws(){while(i<s.size() && (s[i]==' '||s[i]=='\t'||s[i]=='\n'||s[i]=='\r'))++i;}
 bool take(char c){ws();if(i<s.size() && s[i]==c){i++;return true;}return false;}
 void need(char c){if(!take(c))throw std::runtime_error(std::string("invalid JSON, expected ")+c);}
 std::string str(){need('"');std::string o;while(i<s.size()){
  char c=s[i++];if(c=='"')return o;
  if(c=='\\'){
    if(i>=s.size())throw std::runtime_error("invalid JSON escape");
    c=s[i++];if(c=='"'||c=='\\'||c=='/')o+=c;
    else throw std::runtime_error("unsupported JSON escape");
  }else{if(static_cast<unsigned char>(c)<32)throw std::runtime_error("JSON control char");o+=c;}
 }throw std::runtime_error("unterminated JSON string");}
 double number(){ws();if(i>=s.size())throw std::runtime_error("missing number");
  const char* begin=s.c_str()+i;char* end=nullptr;
  errno=0;double val=std::strtod(begin,&end);
  if(end==begin||errno==ERANGE||!std::isfinite(val))throw std::runtime_error("invalid numeric value");
  i+=static_cast<size_t>(end-begin);return val;
 }
 bool boolean(){ws();if(s.compare(i,4,"true")==0){i+=4;return true;}
  if(s.compare(i,5,"false")==0){i+=5;return false;}
  throw std::runtime_error("expected JSON boolean");}
 std::vector<std::vector<double>> vectors(int nparams){
  need('[');std::vector<std::vector<double>> all;
  if(take(']'))throw std::runtime_error("empty parameter vector batch");
  do{
   need('[');std::vector<double> vec;
   if(!take(']')){
    do{double a=number();if(std::abs(a)>0.4)throw std::runtime_error("parameter out of bounds");vec.push_back(a);
      }while(take(','));need(']');
   }
   if(static_cast<int>(vec.size())!=nparams)throw std::runtime_error("wrong parameter dimension");
   all.push_back(std::move(vec));if(all.size()>MAX_VECTORS)throw std::runtime_error("batch too large");
  }while(take(','));need(']');return all;
 }
};
std::vector<std::vector<double>> parse_request(std::string line,const Plan& plan){
 JsonParser p(std::move(line));p.need('{');
 bool has_shifts=false,has_depth=false,has_mode=false,has_op=false;
 std::vector<std::vector<double>> shifts;
 if(!p.take('}'))do{
  auto key=p.str();p.need(':');
  if(key=="shifts"){
    if(has_shifts)throw std::runtime_error("duplicate shifts");shifts=p.vectors(plan.nparams);has_shifts=true;
  }else if(key=="depth"){
    if(has_depth)throw std::runtime_error("duplicate depth");double d=p.number();
    if(d!=plan.nparams)throw std::runtime_error("depth-plan mismatch");has_depth=true;
  }else if(key=="max_terms"){
    double m=p.number();if(m!=plan.max_terms)throw std::runtime_error("term-limit-plan mismatch");
  }else if(key=="observable"){
    if(has_mode)throw std::runtime_error("duplicate mode");if(p.str()!="all_Z")throw std::runtime_error("only all_Z precompiled plan supported");has_mode=true;
  }else if(key=="op"){
    if(has_op)throw std::runtime_error("duplicate op");if(p.str()!="evaluate")throw std::runtime_error("invalid operation");has_op=true;
  }else if(key=="cache"){
    p.boolean();
  }else if(key=="id"){
    p.ws();if(p.i<p.s.size()&&p.s[p.i]=='"')p.str();else p.number();
  }else throw std::runtime_error("unexpected request key: "+key);
 }while(p.take(','));p.need('}');p.ws();if(p.i!=p.s.size()||!has_shifts||!has_depth||!has_mode||!has_op)throw std::runtime_error("incomplete JSON request");
 return shifts;
}

void process(Plan& plan,std::string const& line,int threads){
 auto t=Clock::now();auto vectors=parse_request(line,plan);
 double parse_ms=elapsed_ms(t);t=Clock::now();
 std::vector<std::vector<double>> results;
 results.reserve(vectors.size());
 double bind_ms=0,eval_ms=0;
 for(size_t i=0;i<vectors.size();i++){
   auto b=Clock::now();bind(plan,vectors[i]);bind_ms+=elapsed_ms(b);
   auto e=Clock::now();auto out=evaluate(plan,threads);eval_ms+=elapsed_ms(e);
   for(double v:out)if(!std::isfinite(v))throw std::runtime_error("nonfinite numerical result");
   results.push_back(std::move(out));
 }
 // Serialize atomically, only after the entire requested batch has succeeded.
 std::cout<<"{\"kind\":\"result\",\"ok\":true,\"nqubits\":"<<plan.nqubits<<",\"noutputs\":"<<results.size()<<",\"vectors\":[";
 std::cout<<std::setprecision(17);
 for(size_t i=0;i<results.size();i++){
   if(i)std::cout<<',';
   std::cout<<'[';
   for(size_t j=0;j<results[i].size();j++){
       if(j)std::cout<<',';
       std::cout<<results[i][j];
   }
   std::cout<<']';
 }
 std::cout<<"],\"phases_ms\":{\"parse\":"<<parse_ms<<",\"bind\":"<<bind_ms<<",\"evaluate\":"<<eval_ms<<"}}\n"<<std::flush;
}
int main(int argc,char**argv){
 try{
  if(argc<2||argc>4)throw std::runtime_error("usage: compiled_plan_runner PLAN.bin [threads:1..4] [max_requests:1..256]");
  int threads=argc>2?std::stoi(argv[2]):1;
  int max_req=argc>3?std::stoi(argv[3]):1;
  if(threads<1||threads>4||max_req<1||max_req>256)throw std::runtime_error("invalid worker or request cap");
  auto plan=load_plan(argv[1]);
  std::cout<<"{\"kind\":\"ready\",\"plan_load_ms\":"<<plan.load_ms<<"}\n"<<std::flush;
  std::string line;int count=0;
  while(count<max_req && std::getline(std::cin,line)){
    if(line.size()>1024*1024){std::cout<<"{\"kind\":\"error\",\"ok\":false,\"error\":\"input limit\"}\n"<<std::flush;break;}
    try{process(plan,line,threads);}catch(std::exception const&e){
       std::cout<<"{\"kind\":\"error\",\"ok\":false,\"error\":\"request rejected\"}\n"<<std::flush;
       std::cerr<<"request error: "<<e.what()<<'\n';
    }++count;
  }
  return 0;
 }catch(std::exception const&e){std::cerr<<"plan/launcher error: "<<e.what()<<'\n';return 2;}
}
